// API Configuration
const API_BASE = 'http://localhost:5001';
const REDIRECT_BASE = 'http://localhost:5002';



// DOM Elements
const urlInput = document.getElementById('urlInput');
const createdByInput = document.getElementById('createdBy');
const shortenBtn = document.getElementById('shortenBtn');
const btnText = document.querySelector('.btn-text');
const btnLoading = document.querySelector('.btn-loading');
const resultSection = document.getElementById('resultSection');
const shortUrlDisplay = document.getElementById('shortUrlDisplay');
const originalUrlDisplay = document.getElementById('originalUrlDisplay');
const copyBtn = document.getElementById('copyBtn');

const analyticsInput = document.getElementById('analyticsInput');
const analyticsBtn = document.getElementById('analyticsBtn');
const analyticsResult = document.getElementById('analyticsResult');
const analyticsShortUrl = document.getElementById('analyticsShortUrl');
const totalClicks = document.getElementById('totalClicks');
const recentClicks = document.getElementById('recentClicks');
const clicksList = document.getElementById('clicksList');
const testRedirectBtn = document.getElementById('testRedirectBtn');

// Global Stats
const globalStats = document.getElementById('globalStats');

// Toast notification
function showToast(message, type = 'success') {
    const toast = document.getElementById('toast');
    toast.textContent = message;
    toast.className = `toast ${type} show`;
    setTimeout(() => {
        toast.classList.remove('show');
    }, 3000);
}

// Load global stats
async function loadGlobalStats() {
    try {
        // You can implement a backend endpoint for this, or calculate from existing data
        // For now, we'll use placeholder logic
        const statsHtml = `
            <div class="stat-item">
                <span class="stat-value" id="totalUrls">-</span>
                <span class="stat-label">URLs Created</span>
            </div>
            <div class="stat-item">
                <span class="stat-value" id="totalClicksGlobal">-</span>
                <span class="stat-label">Total Clicks</span>
            </div>
        `;
        globalStats.innerHTML = statsHtml;
    } catch (error) {
        console.error('Failed to load stats:', error);
    }
}

// Shorten URL
async function shortenUrl() {
    const url = urlInput.value.trim();
    const createdBy = createdByInput.value.trim() || 'anonymous';

    if (!url) {
        showToast('Please enter a URL', 'error');
        return;
    }

    // Basic URL validation
    try {
        new URL(url);
    } catch {
        showToast('Please enter a valid URL (include http:// or https://)', 'error');
        return;
    }

    // Show loading
    shortenBtn.disabled = true;
    btnText.style.display = 'none';
    btnLoading.style.display = 'flex';

    try {
        const response = await fetch(`${API_BASE}/shorten`, {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json',
            },
            body: JSON.stringify({
                url: url,
                created_by: createdBy
            })
        });

        if (!response.ok) {
            throw new Error('Failed to shorten URL');
        }

        const data = await response.json();

        // Display result
        shortUrlDisplay.value = data.short_url;
        originalUrlDisplay.textContent = url;
        resultSection.style.display = 'block';

        // Scroll to result
        resultSection.scrollIntoView({ behavior: 'smooth', block: 'nearest' });

        showToast('URL shortened successfully!', 'success');

        // Clear inputs
        urlInput.value = '';
        createdByInput.value = '';

    } catch (error) {
        console.error('Error:', error);
        showToast('Failed to shorten URL. Please try again.', 'error');
    } finally {
        // Hide loading
        shortenBtn.disabled = false;
        btnText.style.display = 'block';
        btnLoading.style.display = 'none';
    }
}

// Copy to clipboard
function copyToClipboard() {
    shortUrlDisplay.select();
    document.execCommand('copy');

    const originalText = copyBtn.innerHTML;
    copyBtn.innerHTML = `
        <svg width="20" height="20" viewBox="0 0 20 20" fill="currentColor">
            <path fill-rule="evenodd" d="M16.707 5.293a1 1 0 010 1.414l-8 8a1 1 0 01-1.414 0l-4-4a1 1 0 011.414-1.414L8 12.586l7.293-7.293a1 1 0 011.414 0z"/>
        </svg>
        Copied!
    `;

    setTimeout(() => {
        copyBtn.innerHTML = originalText;
    }, 2000);

    showToast('Copied to clipboard!', 'success');
}

// Get Analytics
async function getAnalytics() {
    const shortCode = analyticsInput.value.trim();

    if (!shortCode) {
        showToast('Please enter a short code', 'error');
        return;
    }

    analyticsBtn.disabled = true;
    analyticsBtn.textContent = 'Loading...';

    try {
        const response = await fetch(`${REDIRECT_BASE}/analytics/${shortCode}`);

        if (!response.ok) {
            if (response.status === 404) {
                throw new Error('Short URL not found');
            }
            throw new Error('Failed to fetch analytics');
        }

        const data = await response.json();

        // Display analytics
        analyticsShortUrl.textContent = `/${shortCode}`;
        totalClicks.textContent = data.total_clicks || 0;

        // Calculate recent clicks (last 24 hours)
        const safeClicks = data.recent_clicks || [];
        const now = new Date();
        const last24h = data.recent_clicks.filter(click => {
            const clickTime = new Date(click.timestamp);
            const hoursDiff = (now - clickTime) / (1000 * 60 * 60);
            return hoursDiff <= 24;
        });
        recentClicks.textContent = last24h.length;

        // Display recent clicks
        if (safeClicks.length > 0) {
            clicksList.innerHTML = safeClicks.slice(0, 5).map(click => `
                <div class="click-item">
                    <span class="click-time">${click.timestamp ? formatTime(click.timestamp) : 'Unknown time'}</span>
                    <span class="click-ip">${click.ip || 'Unknown'}</span>
                </div>
            `).join('');
        } else {
            clicksList.innerHTML = '<p style="text-align: center; color: var(--gray-600);">No clicks yet</p>';
        }

        // Set up test redirect button
        testRedirectBtn.onclick = () => {
            window.open(`${REDIRECT_BASE}/${shortCode}`, '_blank');
        };

        analyticsResult.style.display = 'block';
        analyticsResult.scrollIntoView({ behavior: 'smooth', block: 'nearest' });

    } catch (error) {
        console.error('Error:', error);
        showToast(error.message || 'Failed to fetch analytics', 'error');
        analyticsResult.style.display = 'none';
    } finally {
        analyticsBtn.disabled = false;
        analyticsBtn.innerHTML = `
            <svg width="20" height="20" viewBox="0 0 20 20" fill="currentColor">
                <path d="M2 11a1 1 0 011-1h2a1 1 0 011 1v5a1 1 0 01-1 1H3a1 1 0 01-1-1v-5zM8 7a1 1 0 011-1h2a1 1 0 011 1v9a1 1 0 01-1 1H9a1 1 0 01-1-1V7zM14 4a1 1 0 011-1h2a1 1 0 011 1v12a1 1 0 01-1 1h-2a1 1 0 01-1-1V4z"/>
            </svg>
            Get Analytics
        `;
    }
}

// Format timestamp
function formatTime(timestamp) {
    const date = new Date(timestamp);
    const now = new Date();
    const diffMs = now - date;
    const diffMins = Math.floor(diffMs / 60000);

    if (diffMins < 1) return 'Just now';
    if (diffMins < 60) return `${diffMins} min ago`;

    const diffHours = Math.floor(diffMins / 60);
    if (diffHours < 24) return `${diffHours} hour${diffHours > 1 ? 's' : ''} ago`;

    const diffDays = Math.floor(diffHours / 24);
    if (diffDays < 7) return `${diffDays} day${diffDays > 1 ? 's' : ''} ago`;

    return date.toLocaleDateString();
}

// Event Listeners
shortenBtn.addEventListener('click', shortenUrl);
urlInput.addEventListener('keypress', (e) => {
    if (e.key === 'Enter') shortenUrl();
});

copyBtn.addEventListener('click', copyToClipboard);

analyticsBtn.addEventListener('click', getAnalytics);
analyticsInput.addEventListener('keypress', (e) => {
    if (e.key === 'Enter') getAnalytics();
});

// Load stats on page load
loadGlobalStats();
